&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;R&#232;gles occultes&lt;a class=&quot;headeranchor&quot; id=&quot;R&#232;gles_occultes_0&quot; href=&quot;#R&#232;gles_occultes_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Occultes.html&quot; title=&quot;Les r&#232;gles occultes&quot;&gt;Pr&#233;sentation&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton1&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;1&#39;);&quot; onmouseout=&quot;outButton(&#39;1&#39;);&quot; onclick=&quot;expandMenu(&#39;1&#39;);&quot; /&gt;
&lt;/div&gt;Mener une partie occulte&amp;emsp;
        &lt;ul ID=&quot;1&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Diriger-Une-Partie-Occulte.html&quot; title=&quot;Diriger une partie occulte&quot;&gt;Diriger une partie occulte&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;Les lieux occultes&lt;/li&gt;
            &lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Les-Esprits-Des-Lieux.html&quot; title=&quot;Les esprits des lieux&quot;&gt;Les esprits des lieux&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nouvelles-R&#232;gles-Sur-Les-Apparitions.html&quot; title=&quot;Nouvelles r&#232;gles sur les apparitions&quot;&gt;Les nouvelles r&#232;gles sur les apparitions&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Les-Lignes-Telluriques.html&quot; title=&quot;Les lignes telluriques&quot;&gt;Les lignes telluriques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paysages-Mentaux.html&quot; title=&quot;Les paysages mentaux&quot;&gt;Les paysages mentaux&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Plans-&#201;sot&#233;riques.html&quot; title=&quot;Plans &#233;sot&#233;riques&quot;&gt;Les plans &#233;sot&#233;riques&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton2&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;2&#39;);&quot; onmouseout=&quot;outButton(&#39;2&#39;);&quot; onclick=&quot;expandMenu(&#39;2&#39;);&quot; /&gt;
&lt;/div&gt;R&#232;gles techniques&amp;emsp;
        &lt;ul ID=&quot;2&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Extensions-De-Comp&#233;tences-Occultes.html&quot; title=&quot;Extensions de comp&#233;tences occultes&quot;&gt;Les extensions de comp&#233;tences occultes&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;La-Magie-Psychique.html&quot; title=&quot;La magie psychique&quot;&gt;La magie psychique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Auras.html&quot; title=&quot;Les auras&quot;&gt;Les auras&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chakras.html&quot; title=&quot;Les chakras&quot;&gt;Les chakras&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Duels-Psychiques.html&quot; title=&quot;Les duels psychiques&quot;&gt;Les duels psychiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Possession-Spirituelle.html&quot; title=&quot;La possession&quot;&gt;La possession spirituelle&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rituels-Occultes.html&quot; title=&quot;Les rituels occultes&quot;&gt;Les rituels occultes&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Exemples-De-Rituels-Occultes.html&quot; title=&quot;Exemples de rituels occultes&quot;&gt;exemples&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Rituel-Occulte.html&quot; title=&quot;Cr&#233;er un rituel occulte&quot;&gt;Cr&#233;er un rituel occulte&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton3&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;3&#39;);&quot; onmouseout=&quot;outButton(&#39;3&#39;);&quot; onclick=&quot;expandMenu(&#39;3&#39;);&quot; /&gt;
&lt;/div&gt;R&#233;compenses occultes&amp;emsp;
        &lt;ul ID=&quot;3&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;quipement-D’Aventurier---Aventures-Occultes.html&quot; title=&quot;&#201;quipement d’aventurier - Aventures occultes&quot;&gt;&#201;quipement d’aventurier&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Alchimiques---Aventures-Occultes.html&quot; title=&quot;Objets alchimiques - Aventures occultes&quot;&gt;Objets alchimiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Magiques---Aventures-Occultes.html&quot; title=&quot;Objets magiques - Aventures occultes&quot;&gt;Objets magiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Maudits---Aventures-Occultes.html&quot; title=&quot;Objets maudits - Aventures occultes&quot;&gt;Objets maudits&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artefacts---Aventures-Occultes.html&quot; title=&quot;Artefacts - Aventures occultes&quot;&gt;Artefacts&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;Voici une s&#233;lection de rituels occultes. Ils sont pr&#233;sent&#233;s comme des sorts mais poss&#232;dent deux entr&#233;es suppl&#233;mentaires : le contrecoup et l’&#233;chec.&lt;br /&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Appeler par-del&#224; le voile&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;APPELERPARDELALEVOILE&quot; href=&quot;#APPELERPARDELALEVOILE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Invocation.html&quot; title=&quot;Invocation&quot;&gt;Invocation&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Appel.html&quot; title=&quot;Appel&quot;&gt;appel&lt;/a&gt;) ; &lt;b&gt;Niveau&lt;/b&gt; 6&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 60 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt;  V, G, F (un objet ayant appartenu &#224; l’entit&#233; ou l’esprit appel&#233; ou le nom de cette cr&#233;ature), OS (jusqu’&#224; 8)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plans) DD 33, 1 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion) DD 33, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; DD 31, 2 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; officiant principal&lt;/li&gt;&lt;li&gt;&lt;b&gt;Effet&lt;/b&gt; appelle l’esprit d’une unique cr&#233;ature d&#233;c&#233;d&#233;e ou une entit&#233; psychique&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; concentration de l’officiant principal&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; Volont&#233; annule ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; non&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; tous les officiants sont &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puis&#233;s&lt;/a&gt; et gagnent un &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveau n&#233;gatif&lt;/a&gt; temporaire (DD = 16 + bonus de Charisme de l’officiant principal pour s’en d&#233;barrasser apr&#232;s la premi&#232;re journ&#233;e)&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; tous les officiants gagnent un &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveau n&#233;gatif&lt;/a&gt; permanent et sont &#233;puis&#233;s jusqu’&#224; ce qu’ils s’en soient d&#233;barrass&#233;s&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
L’officiant principal tente d’obliger l’esprit d’un individu pr&#233;cis ou d’une entit&#233; psychique particuli&#232;re &#224; se manifester depuis sa derni&#232;re demeure ou son foyer extraplanaire. Si l’esprit ou l’entit&#233; ne veut pas r&#233;pondre &#224; l’appel, il ou elle peut refuser &#224; condition de r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;. Dans ce cas, la cr&#233;ature ne se manifeste pas mais le rituel est tout de m&#234;me consid&#233;r&#233; comme un succ&#232;s. Si l’&#234;tre appel&#233; rate son jet ou veut bien r&#233;pondre &#224; l’appel, il appara&#238;t dans le corps de l’officiant principal. Il s’exprime alors par sa bouche et sa voix prend une tonalit&#233; d’outre-tombe. Il s’exprime &#224; travers l’officiant principal mais n’exerce aucun contr&#244;le sur lui, ni sur son esprit ni sur son corps, et ne peut pas lancer de sort, ni utiliser de pouvoir magique ni de pouvoir surnaturel mental, m&#234;me s’il dispose de ces capacit&#233;s. Il est oblig&#233; de quitter le corps de l’officiant principal d&#232;s que celui-ci rompt sa concentration. Tant que l’esprit s’exprime par l’interm&#233;diaire de l’officiant principal, les officiants secondaires peuvent lui poser des questions, au rythme d’une par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; au maximum (quel que soit le nombre d’officiants secondaires). L’&#234;tre appel&#233; parle dans un langage qu’il conna&#238;t ou connaissait de son vivant. Il peut refuser de r&#233;pondre &#224; une question ou tenter de duper ses interlocuteurs et l’officiant principal avec &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;. Les officiants n’ont pas de contr&#244;le sur lui.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Capture d&#39;&#226;me&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CAPTURTEDAME&quot; href=&quot;#CAPTURTEDAME&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Livre des Damn&#233;s 2 (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Book of the Damned/Livre des damn&#233;s&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoBD.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Necromancie.html&quot; title=&quot;N&#233;cromancie&quot;&gt;N&#233;cromancie&lt;/a&gt; [&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;Mal&lt;/a&gt;] ; &lt;b&gt;Niveau&lt;/b&gt; 9&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 90 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt;  V, G, M (une lentille de cristal valant au moins la moiti&#233; de la valeur de l&#39;&#226;me &#224; pi&#233;ger), OS (jusqu’&#224; 12)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; DD 31, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plans) DD 31, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion) DD 31, 3 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; courte&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; une cr&#233;ature vivante ou r&#233;cemment morte&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; instantan&#233;e&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;, annule ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; non&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; Tous les officiants acqui&#232;rent chacun 1 &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveau n&#233;gatif&lt;/a&gt; temporaire.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; Tous les officiants deviennent &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Chancelant.html&quot; title=&quot;Chancelant&quot;&gt;chancelants&lt;/a&gt; pendant 10 minutes. &#192; moins que le rituel n&#39;ait &#233;t&#233; effectu&#233; dans une zone qui interdit les d&#233;placements dimensionnels, cette r&#233;action attire l&#39;attention d&#39;un ou plusieurs &lt;a class=&quot;pagelink&quot; href=&quot;Psychopompes.html&quot; title=&quot;Les psychopompes&quot;&gt;psychopompes&lt;/a&gt; d&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; total &#233;gal au FP de la cr&#233;ature dont les officiants tentaient de pi&#233;ger l&#39;&#226;me, et la r&#233;action magique permet aux psychopompes de se manifester &#224; l&#39;endroit du rituel afin de punir les officiants pour avoir jou&#233; avec les &#226;mes.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
Le corps de la cr&#233;ature dont l&#39;&#226;me doit &#234;tre pi&#233;g&#233;e doit &#234;tre &#224; port&#233;e du rituel pendant toute la dur&#233;e. Si le corps est retir&#233; de cette zone avant que le rituel ne soit termin&#233;, le rituel &#233;choue imm&#233;diatement (d&#233;clenchant le r&#233;sultat d&#39;&#233;chec d&#233;taill&#233; ci-dessus). Si la cr&#233;ature cibl&#233;e est vivante, elle doit &#234;tre tu&#233;e &#224; un moment donn&#233; pendant le temps d&#39;incantation du rituel ; traditionnellement, cela se produit &#224; la fin du rituel, de sorte que si la victime r&#233;siste &#224; ce que son &#226;me soit pi&#233;g&#233;e avec un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; r&#233;ussi, les officiants pourraient potentiellement essayer de capturer l&#39;&#226;me une deuxi&#232;me fois en commen&#231;ant imm&#233;diatement un deuxi&#232;me rituel. Si la cr&#233;ature cibl&#233;e &#233;tait d&#233;j&#224; morte, elle ne doit pas &#234;tre morte depuis plus d&#39;une minute avant le d&#233;but du rituel de capture d&#39;&#226;me, et dans ce cas, l&#39;&#226;me de la cr&#233;ature peut toujours tenter un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour r&#233;sister aux effets comme si elle &#233;tait encore en vie.&lt;br /&gt;&lt;br /&gt;Si le rituel r&#233;ussit, l&#39;&#226;me de la cr&#233;ature se transforme en une &lt;a class=&quot;pagelink&quot; href=&quot;Magie-Des-&#194;mes.html&quot; title=&quot;Magie des &#226;mes&quot;&gt;gemme spirituelle&lt;/a&gt; scintillante. Cette gemme est un objet fin fragile qui a une &lt;a class=&quot;pagelink&quot; href=&quot;Exploration#Solidite.html&quot; title=&quot;solidit&#233;&quot;&gt;solidit&#233;&lt;/a&gt; de 2 et 1 point de r&#233;sistance. Dans cet &#233;tat, l&#39;&#226;me ne peut en aucun cas &#234;tre ramen&#233;e &#224; la vie ; la gemme spirituelle doit d&#39;abord &#234;tre d&#233;truite, auquel cas les m&#233;thodes de r&#233;surrections de cr&#233;ature fonctionnent normalement.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Cercle d&#39;enchev&#234;trement&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CERCLEDENCHEVETREMENT&quot; href=&quot;#CERCLEDENCHEVETREMENT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Abjuration.html&quot; title=&quot;Abjuration&quot;&gt;Abjuration&lt;/a&gt; (variable, voir texte) ; &lt;b&gt;Niveau&lt;/b&gt; 4&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 40 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt;  V, G, M (poudre d’argent), F (un stylet en mithral et en diamant d’une valeur de 5 000 po), OS (jusqu’&#224; 8)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plans) DD 30, 2 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion) DD 30, 1 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt; DD 30, 1 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; 3 m&lt;/li&gt;&lt;li&gt;&lt;b&gt;Effet&lt;/b&gt; un cercle magique de 6 m de rayon&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 jour/niveau de personnage de l’officiant principal&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; Volont&#233; annule (inoffensif ) ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; non, voir texte&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; l’officiant principal re&#231;oit 2d6 points de d&#233;g&#226;ts.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; les officiants pensent qu’ils ont r&#233;ussi le rituel mais le cercle n’a aucun effet quand ils tentent de l’utiliser.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
Lors de ce rituel, les officiants doivent cr&#233;er un grand cercle magique en jetant la poudre d’argent sur son pourtour qu’ils fa&#231;onnent ensuite avec le stylet qui leur sert de focalisateur. Ce cercle doit &#234;tre trac&#233; avec grand soin, afin de l’harmoniser avec l’alignement d&#233;sir&#233; (Bien, Chaos, Loi ou Mal), &#224; choisir au moment de sa cr&#233;ation. Le rituel appartient au registre de l’alignement choisi. Une fois le cercle termin&#233;, il devient invisible, sauf aux yeux des officiants ayant particip&#233; au rituel ou des cr&#233;atures dot&#233;es de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-Linvisibilit&#233;.html&quot; title=&quot;D&#233;tection de l&amp;#39;invisibilit&#233;&quot;&gt;d&#233;tection de l’invisibilit&#233;&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vision-Lucide.html&quot; title=&quot;Vision lucide&quot;&gt;vision lucide&lt;/a&gt;&lt;/i&gt; ou une autre m&#233;thode pour discerner les objets invisibles.&lt;br /&gt;&lt;br /&gt;Une fois le cercle termin&#233;, il sert &#224; pi&#233;ger un ext&#233;rieur dont le sous-type correspond &#224; l’alignement choisi, comme s’il s’agissait d’un cercle magique dirig&#233; vers l’int&#233;rieur du type appropri&#233; (un cercle d’enchev&#234;trement harmonis&#233; sur le Mal fonctionne donc comme un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cercle-Magique-Contre-Le-Mal.html&quot; title=&quot;Cercle magique contre le Mal&quot;&gt;cercle magique contre le Mal&lt;/a&gt;&lt;/i&gt; tourn&#233; vers l’int&#233;rieur). Pour qu’un ext&#233;rieur se fasse pi&#233;ger ainsi, il faut que la totalit&#233; de l’espace qu’il occupe soit contenue dans le cercle. &#192; ce moment, l’officiant principal peut activer le cercle par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Immediate.html&quot; title=&quot;Action imm&#233;diate&quot;&gt;action imm&#233;diate&lt;/a&gt;. Pour activer le cercle, l’officiant principal doit se trouver &#224; 30 m&#232;tres ou moins du cercle. Il doit aussi &#234;tre en mesure de le voir et de voir l’ext&#233;rieur qu’il souhaite pi&#233;ger. Il peut pi&#233;ger plusieurs ext&#233;rieurs du sous-type appropri&#233; s’ils se trouvent dans le cercle au moment de l’activation. Cependant, si un ext&#233;rieur ne se trouve pas enti&#232;rement dans le cercle, il n’est pas pris au pi&#232;ge et peut effacer le cercle, comme indiqu&#233; dans la description du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cercle-Magique-Contre-Le-Mal.html&quot; title=&quot;Cercle magique contre le Mal&quot;&gt;cercle magique contre le Mal&lt;/a&gt;&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;Comme avec un cercle magique, l’ext&#233;rieur pi&#233;g&#233; ne peut pas franchir les limites du cercle, ni tendre un appendice au-del&#224; de ces limites ou au-dessus d’elles et ne peut pas non plus d&#233;truire le cercle, ni directement, ni indirectement. En revanche, il peut effectuer des attaques &#224; distance au-del&#224; des limites du cercle. Si l’ext&#233;rieur dispose d’une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;RM&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt;, il peut mettre le pi&#232;ge &#224; l’&#233;preuve une fois par jour. Si l’officiant principal n’arrive pas &#224; surmonter la r&#233;sistance &#224; la magie de l’ext&#233;rieur, le cercle s’efface et l’ext&#233;rieur est libre. Un ext&#233;rieur capable de se d&#233;placer &#224; travers les dimensions peut quitter le cercle ainsi.&lt;br /&gt;&lt;br /&gt;Contrairement au cercle magique, le cercle d’enchev&#234;trement ne permet pas de renforcer sa s&#233;curit&#233; &#224; l’aide d’un diagramme.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Communion hant&#233;e&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;COMMUNIONHANTEE&quot; href=&quot;#COMMUNIONHANTEE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Necromancie.html&quot; title=&quot;N&#233;cromancie&quot;&gt;N&#233;cromancie&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; 7&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d’incantation&lt;/b&gt; 70 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt; V, G, M (des peintures sp&#233;ciales et une petite p&#226;tisserie sal&#233;e), F (cloche en argent d’une valeur de 500 po), OS (jusqu’&#224; 18)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res) DD 31, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion) DD 31, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt; DD 31, 1 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; contact&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; une apparition dans un rayon de 18 m&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 heure et 10 rounds (D) ; voir texte&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; Volont&#233; annule ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; oui&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; l’officiant principal est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puis&#233;&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; les officiants re&#231;oivent 1 niveau n&#233;gatif permanent et un malus de –4 &#224; tous les tests de comp&#233;tence et de caract&#233;ristique tant qu’ils ne se sont pas d&#233;barrass&#233;s de leur niveau n&#233;gatif.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
Ce rituel doit s’accomplir dans un rayon de 18 m&#232;tres autour d’une &lt;a class=&quot;pagelink&quot; href=&quot;Apparitions.html&quot; title=&quot;Les apparitions&quot;&gt;apparition&lt;/a&gt;. L’officiant principal fait tinter la cloche d’argent &#224; l’aide d’un objet associ&#233; &#224; l’origine de l’apparition ou &#224; sa source de pouvoir. Ensuite, il dessine un cercle complexe orn&#233; de symboles occultes autour du plat o&#249; se trouve la petite p&#226;tisserie sal&#233;e. Si l’incantation est un succ&#232;s, l’esprit de l’apparition entre dans la p&#226;tisserie (l’apparition devenant inerte pendant toute la dur&#233;e du rituel). L’un des officiants doit manger la p&#226;tisserie avant la fin de l’heure suivante, sans quoi le rituel se termine. Si personne ne mange la p&#226;tisserie, l’apparition se lib&#232;re. Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de tous ses effets augmente de 4 et elle b&#233;n&#233;ficie d’un bonus de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d’attaque&lt;/a&gt; pendant 24 heures. Une fois qu’un officiant a mang&#233; la p&#226;tisserie, l’esprit de l’apparition s’exprime par sa bouche et doit r&#233;pondre honn&#234;tement &#224; 10 questions (une par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;) avant de s’en aller. Ceci dit, si l’apparition est un &#233;cho &#233;motionnel, ses r&#233;ponses risquent d’&#234;tre cryptiques, br&#232;ves ou r&#233;p&#233;titives, comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communication-Avec-Les-Morts.html&quot; title=&quot;Communication avec les morts&quot;&gt;communication avec les morts&lt;/a&gt;&lt;/i&gt;. Une fois que l’apparition a r&#233;pondu &#224; 10 questions ou que le sort se termine, l’apparition se manifeste de nouveau normalement.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;D&#233;chirer le voile des r&#234;ves&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DECHIRERLEVOILEDESREVES&quot; href=&quot;#DECHIRERLEVOILEDESREVES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Invocation.html&quot; title=&quot;Invocation&quot;&gt;Invocation&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Creation.html&quot; title=&quot;cr&#233;ation&quot;&gt;cr&#233;ation&lt;/a&gt;) ; &lt;b&gt;Niveau&lt;/b&gt; 6&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d’incantation&lt;/b&gt; 60 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt; V, G, M (de l’encens br&#251;lant dans un bol tapiss&#233; de terre venant d’une tombe, une bouteille de vin d’absinthe par officiant), F (une clef ornement&#233;e en mithral et en argent d’une valeur de 5 000 po), OS (pas plus que le modificateur d’Intelligence de l’officiant principal)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence &lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res) DD 32, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plans) DD 32, 3 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; contact&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; instantan&#233;e, voir texte&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde &lt;/b&gt;aucun ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; non&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; l’officiant principal re&#231;oit 2d6 points de d&#233;g&#226;ts et se trouve &lt;a class=&quot;pagelink&quot; href=&quot;../&#201;tats pr&#233;judiciables#Fatigu&#233;

Un personnage fatigu&#233; est dans l’incapacit&#233; de courir et de charger/-Il-Subit-Un-Malus-De--2-En-Force-Ainsi-Qu’En-Dext&#233;rit&#233;.html&quot; title=&quot;Fatigu&#233;&quot;&gt;fatigu&#233;&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; un &lt;a class=&quot;pagelink&quot; href=&quot;R&#234;ve-Anim&#233;.html&quot; title=&quot;R&#234;ve anim&#233;&quot;&gt;r&#234;ve anim&#233;&lt;/a&gt; appara&#238;t sur les lieux du rituel et s’attaque aux officiants. Si le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; le d&#233;sire, ce r&#234;ve peut b&#233;n&#233;ficier de l’arch&#233;type &lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types.html#CREATUREEVOLUEE&quot; title=&quot;Les arch&#233;types&quot;&gt;&#233;volu&#233;&lt;/a&gt;, &#234;tre accompagn&#233; d’autres r&#234;ves, ou les deux.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
Ce rituel se c&#233;l&#232;bre obligatoirement de nuit sur le plan Mat&#233;riel. Les officiants boivent le vin d’absinthe avant d’entonner l’incantation tandis que l’encens se consume. Les officiants m&#233;langent ensuite les cendres de l’encens avec la terre de la tombe et utilisent cette mixture pour tracer une porte avec une serrure. Ils ins&#232;rent la clef dans cette serrure &#224; la fin de l’incantation. En cas de succ&#232;s, ils franchissent la porte et se trouvent quelque part dans la &lt;a class=&quot;pagelink&quot; href=&quot;Plans-&#201;sot&#233;riques.html#DIMENSIONDUREVE&quot; title=&quot;Plans &#233;sot&#233;riques&quot;&gt;dimension du R&#234;ve&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;Si les officiants d&#233;sirent retourner sur le plan Mat&#233;riel alors qu’ils se trouvent dans la dimension du R&#234;ve, ils doivent tous r&#233;ussir un &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;test de concentration&quot;&gt;test de concentration&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 35. C’est une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt; qui ne provoque pas d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;Attaque d&amp;#39;opportunit&#233; (redirection)&quot;&gt;attaque d’opportunit&#233;&lt;/a&gt;. Le DD de ce test est r&#233;duit de 1 par tranche de 2d6 points de d&#233;g&#226;ts que le voyageur accepte de recevoir lors de son action complexe suite &#224; des traumatismes psychiques et physiques (il est impossible de r&#233;duire ces d&#233;g&#226;ts, de quelque mani&#232;re que ce soit). Si l’officiant r&#233;ussit son test, il est emport&#233; sur le plan Mat&#233;riel, l&#224; o&#249; il a c&#233;l&#233;br&#233; le rituel. Les officiants qui ratent leur test de concentration peuvent le refaire. Si l’officiant n’est pas un lanceur de sorts, il utilise son niveau de personnage + son modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; comme bonus au test de concentration. Il utilise aussi cette valeur si elle est sup&#233;rieure &#224; son bonus de concentration habituel.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;D&#233;chirure &#233;th&#233;r&#233;e&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DECHIRUREETHEREE&quot; href=&quot;#DECHIRUREETHEREE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Evocation.html&quot; title=&quot;&#201;vocation&quot;&gt;&#201;vocation&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; 5&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d’incantation&lt;/b&gt; 50 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt; V, G, M (une bonne cuiller&#233;e d’ectoplasme et de p&#226;te de racine de lotus broy&#233;e d’une valeur de 500 po), F (une dague en obsidienne dot&#233;e d’un bonus d’alt&#233;ration minimum de +2 et de la propri&#233;t&#233; spectrale d’une valeur minimum de 18 301 po)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (g&#233;ographie) DD 29, 2 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plans) DD 29, 3 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; contact&lt;/li&gt;&lt;li&gt;&lt;b&gt;Effet&lt;/b&gt; une d&#233;chirure entre les plans Mat&#233;riel et &#201;th&#233;r&#233;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 heure/niveau de personnage de l’officiant principal et instantan&#233;, voir texte&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; R&#233;flexes annule ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; non&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; l’officiant re&#231;oit 4d6 points de d&#233;g&#226;ts.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; l’officiant devient de sous-type &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Intangible.html&quot; title=&quot;Intangible (sous-type)&quot;&gt;intangible&lt;/a&gt; et reste &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Confus.html&quot; title=&quot;Confus&quot;&gt;confus&lt;/a&gt; pendant 24 heures.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
&#192; la fin du rituel, la dague devient capable d’ouvrir une br&#232;che entre le &lt;a class=&quot;pagelink&quot; href=&quot;Plans-&#201;sot&#233;riques.html#PLANMATERIEL&quot; title=&quot;Plans &#233;sot&#233;riques&quot;&gt;plan Mat&#233;riel&lt;/a&gt; et le &lt;a class=&quot;pagelink&quot; href=&quot;Plans-&#201;sot&#233;riques.html#PLANETHERE&quot; title=&quot;Plans &#233;sot&#233;riques&quot;&gt;plan &#201;th&#233;r&#233;&lt;/a&gt;, mais seulement si l’officiant s’en tient aux restrictions du rituel.&lt;br /&gt;&lt;br /&gt;Au d&#233;but du rituel, l’officiant doit trouver l’endroit parfait pour pratiquer son incision : un endroit o&#249; les caract&#233;ristiques du plan Mat&#233;riel et du plan &#201;th&#233;r&#233; sont &#233;troitement align&#233;es (c’est au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; de d&#233;terminer l’endroit exact). Ensuite, apr&#232;s avoir marmonn&#233; une incantation amenuisant les fronti&#232;res entre ces deux plans &#224; cet endroit, il doit enduire toute la lame de son focalisateur avec la mixture issue des composantes mat&#233;rielles. Une fois ces conditions remplies, le rituel est termin&#233; avec succ&#232;s et l’officiant re&#231;oit le contrecoup mais il peut retarder l’effet du rituel. Tant qu’il ne quitte pas sa case et continue de tenir la dague de focalisation, il peut l’utiliser pour d&#233;couper la fronti&#232;re affaiblie entre les plans par une action simple qui ne provoque pas d’attaque d’opportunit&#233;. Cependant, il doit ouvrir la br&#232;che dans un d&#233;lai maximum d’une heure par niveau de personnage apr&#232;s avoir termin&#233; le rituel et subi le contrecoup. Cette action a un effet imm&#233;diat et dramatique : la d&#233;chirure tente d’aspirer toutes les cr&#233;atures et tous les objets abandonn&#233;s pesant moins de 100 kilos situ&#233;s dans un rayon de 9 m&#232;tres autour de la case de l’officiant. Si la d&#233;chirure se fait sur le plan Mat&#233;riel, la faille aspire ses victimes sur le plan &#201;th&#233;r&#233; et inversement. Une cr&#233;ature &#233;chappe &#224; cette aspiration si elle r&#233;ussit un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt;. Les cr&#233;atures et objets aspir&#233;s dans la d&#233;chirure arrivent dans l’espace correspondant sur l’autre plan. L’officiant c&#233;l&#233;brant le rituel a le choix : se faire aspirer dans la br&#232;che ou rester sur le plan o&#249; il a men&#233; la c&#233;r&#233;monie.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Deuxi&#232;me apoth&#233;ose&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DEUXIEMEAPOTHEOSE&quot; href=&quot;#DEUXIEMEAPOTHEOSE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Livre des Damn&#233;s 2 (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Book of the Damned/Livre des damn&#233;s&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoBD.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;Transmutation&lt;/a&gt; [&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;Mal&lt;/a&gt;] ; &lt;b&gt;Niveau&lt;/b&gt; 5&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 5 heures&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt;  V, G, M (de l&#39;encens exotique d&#39;une valeur de 500 po, offrande br&#251;l&#233;e d&#39;un membre de la famille)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; DD 23, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plan ou religion) DD 23, 2 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; personnelle&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; officiant principal&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; instantan&#233;e&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; zucun ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; non&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; L&#39;officiant principal subit 4d6 points de d&#233;g&#226;ts et est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puis&#233;s&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; L&#39;officiant principal devient &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Inconscient.html&quot; title=&quot;Inconscient&quot;&gt;inconscient&lt;/a&gt; pendant 2d4 heures.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
La pr&#233;paration de la deuxi&#232;me apoth&#233;ose n&#233;cessite encore de nombreux mois d&#39;actes d&#233;gradants et de complots ignobles, mais &#224; un moment donn&#233; au cours de cette deuxi&#232;me ann&#233;e, l&#39;officiant principal doit contacter le protecteur fi&#233;lon qu&#39;il a choisi choisi, soit gr&#226;ce &#224; une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communion.html&quot; title=&quot;Communion&quot;&gt;communion&lt;/a&gt;&lt;/i&gt; soit gr&#226;ce &#224; un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contact-Avec-Les-Plans.html&quot; title=&quot;Contact avec les plans&quot;&gt;contact avec les plans&lt;/a&gt;&lt;/i&gt;. Un serviteur ou un alli&#233; de confiance peut lancer ce sort au nom de l&#39;officiant principal ; il est courant pour un officiant principal d&#39;acqu&#233;rir un familier &lt;a class=&quot;pagelink&quot; href=&quot;Cacoda&#233;mon.html&quot; title=&quot;Da&#233;mon, Cacoda&#233;mon&quot;&gt;cacoda&#233;mon&lt;/a&gt;, un &lt;a class=&quot;pagelink&quot; href=&quot;Diablotin.html&quot; title=&quot;Diable, Diablotin&quot;&gt;diablotin&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;Quasit.html&quot; title=&quot;D&#233;mon, Quasit&quot;&gt;quasit&lt;/a&gt; afin qu&#39;il puisse utiliser son pouvoir magique de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communion.html&quot; title=&quot;Communion&quot;&gt;communion&lt;/a&gt;&lt;/i&gt; &#224; cette fin. Une fois le contact pris, le protecteur doit &#234;tre inform&#233; du d&#233;sir de l&#39;officiant principal de devenir un fi&#233;lon ; durant ce temps, le sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communion.html&quot; title=&quot;Communion&quot;&gt;communion&lt;/a&gt;&lt;/i&gt; ou de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Contact-Avec-Les-Plans.html&quot; title=&quot;Contact avec les plans&quot;&gt;Contact avec les plans&lt;/a&gt;&lt;/i&gt; ne peut pas &#234;tre utilis&#233; pour poser d&#39;autres questions. &#192; tout moment par la suite, mais avant qu&#39;un an ne se soit &#233;coul&#233;, l&#39;officiant principal doit offrir un sacrifice important &#224; son protecteur fi&#233;lon sous forme d&#39;offrande br&#251;l&#233;e dans un temple consacr&#233; au fi&#233;lon. Cette offrande peu &#234;tre vivante ou morte, mais l&#39;offrande br&#251;l&#233;e doit appartenir &#224; quelqu&#39;un qui est li&#233; &#224; l&#39;officiant principal par le sang ou la famille (comme un conjoint, un parent ou un enfant adoptif) et l&#39;officiant principal et l&#39;offrande doivent avoir partag&#233; au moins une fois un lien &#233;motionnel positif tel que l&#39;amour ou la fiert&#233;. Si ce rituel &#233;choue, l&#39;officiant principal peut r&#233;essayer, bien que le nombre de tentatives qu&#39;il peut faire soit limit&#233; dans la mesure o&#249; chaque nouvelle tentative n&#233;cessite une offrande br&#251;l&#233;e d&#39;un proche diff&#233;rent. Une fois la deuxi&#232;me apoth&#233;ose r&#233;ussie, une partie du corps de l&#39;officiant principal est d&#233;natur&#233;e par une caract&#233;ristique fi&#233;lonne, comme preuve de la faveur de son protecteur. Utilisez les diff&#233;rentes greffes de chair pour mod&#233;liser ces transformations partielles ; la transformation sp&#233;cifique accord&#233;e d&#233;pend du MJ, mais les r&#233;sultats typiques incluent un &lt;i&gt;gantelet &#224; griffes&lt;/i&gt; ou des &lt;i&gt;ailes de t&#233;n&#232;bres&lt;/i&gt;. Une fois la deuxi&#232;me apoth&#233;ose accomplie, l&#39;officiant principal devient &#233;ligible pour entreprendre la &lt;a class=&quot;pagelink&quot; href=&quot;Exemples-De-Rituels-Occultes.html#TROISIEMEAPOTHEOSE&quot; title=&quot;Exemples de rituels occultes&quot;&gt;troisi&#232;me apoth&#233;ose&lt;/a&gt;.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Disjonction en quart&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DISJONCTIONENQUART&quot; href=&quot;#DISJONCTIONENQUART&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Livre des Damn&#233;s 2 (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Book of the Damned/Livre des damn&#233;s&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoBD.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;Transmutation&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; 9&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 90 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt;  V, G, M (9 doses d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Eau-B&#233;nite-(Objet).html&quot; title=&quot;Eau b&#233;nite&quot;&gt;eau b&#233;nite&lt;/a&gt;), F (&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Livre-Des-Damn&#233;s.html&quot; title=&quot;Livre des damn&#233;s&quot;&gt;Livre des damn&#233;s&lt;/a&gt;&lt;/i&gt; int&#233;gral)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; DD 35, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (livres) DD 35, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plan) DD 35, 3 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; contact&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Livre-Des-Damn&#233;s.html&quot; title=&quot;Livre des damn&#233;s&quot;&gt;Livre des damn&#233;s&lt;/a&gt;&lt;/i&gt; int&#233;gral&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; instantan&#233;e&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; aucun ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; non&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; L&#39;officiant principal devient &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puis&#233;&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; L&#39;officiant principal est entra&#238;n&#233; dans le demi-plan du &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Livre-Des-Damn&#233;s.html&quot; title=&quot;Livre des damn&#233;s&quot;&gt;livre des damn&#233;s&lt;/a&gt;&lt;/i&gt; et est soumis aux effets d&#39;un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;bilit&#233;.html&quot; title=&quot;D&#233;bilit&#233;&quot;&gt;d&#233;bilit&#233;&lt;/a&gt;&lt;/i&gt; (NLS 20) ; le &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Livre-Des-Damn&#233;s.html&quot; title=&quot;Livre des damn&#233;s&quot;&gt;livre des damn&#233;s&lt;/a&gt;&lt;/i&gt; est transport&#233; &#224; un endroit al&#233;atoire sur un monde d&#39;un plan Mat&#233;riel al&#233;atoire.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
La premi&#232;re &#233;tape de la destruction du &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Livre-Des-Damn&#233;s.html&quot; title=&quot;Livre des damn&#233;s&quot;&gt;Livre des damn&#233;s&lt;/a&gt;&lt;/i&gt; consiste &#224; diviser le livre en quatre sections - une pour chacune de ses parties d&#233;moniaques, da&#233;moniques, diabloliques, et son apocryphe. S&#233;parer le livre en ces quatre parties est &#224; la fois difficile et dangereux. Le rituel n&#233;cessite de frotter les pages avec de l&#39;eau b&#233;nite et de r&#233;citer des formules magiques puissantes tout en lisant des phrases cl&#233;s cach&#233;es dans le texte. Une fois le rituel termin&#233; avec succ&#232;s, le &lt;i&gt;Livre des damn&#233;s&lt;/i&gt; se s&#233;pare en ses quatre composants, chacun d&#39;eux devant &#234;tre rapidement s&#233;par&#233; les uns des autres, car si les quatre composants du &lt;i&gt;livre des damn&#233;s&lt;/i&gt; se trouvaient &#224; moins de 9 m&#232;tres les uns des autres une fois qu&#39;une minute s&#39;est &#233;coul&#233;e apr&#232;s leur s&#233;paration, ils se reforment imm&#233;diatement en &lt;i&gt;Livre des damn&#233;s&lt;/i&gt; int&#233;gral comme si la disjonction en quart n&#39;avait jamais &#233;t&#233; effectu&#233;.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Exorcisme rituel&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;EXORCISMERITUEL&quot; href=&quot;#EXORCISMERITUEL&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Abjuration.html&quot; title=&quot;Abjuration&quot;&gt;Abjuration&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; 4&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d’incantation&lt;/b&gt; 40 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt; V, G, M (fiole d’eau b&#233;nite), F (symbole sacr&#233; en argent), OS (jusqu’&#224; 12)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; DD 28, 2 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion) DD 28, 2 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; courte (7,50 m + 1,50 m/niveau de l’officiant principal)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; 1 cr&#233;ature poss&#233;d&#233;e sans d&#233;fense ou un objet poss&#233;d&#233; attach&#233;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; instantan&#233;e&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; Volont&#233; annule ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; oui&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; tous les officiants sont &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puis&#233;s&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; tous les officiants gagnent un &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveau n&#233;gatif&lt;/a&gt; temporaire (DD = 16 + bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; de l’officiant principal pour s’en d&#233;barrasser apr&#232;s le premier jour) et l’officiant principal subit 4d6 points de d&#233;g&#226;ts.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
L’officiant oblige la force vitale d’une cr&#233;ature en poss&#233;dant une autre &#224; quitter son h&#244;te. &#192; la fin du rituel, cette cr&#233;ature tente un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;. Si elle &#233;choue, elle est chass&#233;e de son h&#244;te, comme si la dur&#233;e du sort ou de l’effet utilis&#233; pour prendre possession de l’h&#244;te &#233;tait arriv&#233;e &#224; terme. Si la cr&#233;ature r&#233;ussit son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt;, elle reste dans son h&#244;te, cr&#233;ature ou objet, mais les officiants peuvent recommencer le rituel tant que l’h&#244;te poss&#233;d&#233; est sans d&#233;fense ou que l’objet est attach&#233;.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Foyer de Valenhall&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;FOYERDEVALENHALL&quot; href=&quot;#FOYERDEVALENHALL&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Origines occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Origins/Origines occultes ; /!\ Traduit par la communaut&#233; /!\&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOO.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Abjuration.html&quot; title=&quot;Abjuration&quot;&gt;Abjuration&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; 4&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 4 heures&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt; V, S, F (une lanterne en fer froid et en argent valant 5 000 po), OS (jusqu&#39;&#224; 12)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res) DD 29, 2 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; DD 29, 2 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; contact&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; Un vaisseau ou un navire (jusqu&#39;&#224; 3 m&#178;/niveau de personnage de l&#39;officiant principal)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 an&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jets de sauvegarde&lt;/b&gt; aucun ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; oui&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contre coup&lt;/b&gt; l&#39;officiant principal subit 2d6 points de d&#233;g&#226;ts de feu et tous les officiants se retrouvent &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puis&#233;s&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; Tous les officiants sont gel&#233;s et ne peuvent pas se r&#233;chauffer pendant 24 heures (&#224; la min&#232;re de l&#39;exposition &#224; une &lt;a class=&quot;pagelink&quot; href=&quot;Dangers-Naturels.html#FROID&quot; title=&quot;Les dangers naturels&quot;&gt;temp&#233;rature basse&lt;/a&gt;, sans prendre en compte le climat ext&#233;rieur).&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
Pratique jalousement gard&#233;e par souverains du Royaume glac&#233; des vikings, ce rituel vient d&#39;une ancienne tradition perp&#233;tu&#233;e par le peuple du grand nord pour survivre dans la Calotte glaciaire. Apr&#232;s des heures &#224; chanter, &#224; faire des sculptures de bois, et des onstructions de feu, l&#39;officiant principal lance une lanterne d&#39;argent dans un feu de joie d&#233;cha&#238;n&#233; puis la r&#233;cup&#232;re &#224; mains nues. Le rituel imbibe la lanterne d&#39;une flamme jaune inextinguible pendant 1 an. Lorsqu&#39;elle est attach&#233;e &#224; la proue ou au mat d&#39;un navire, la lanterne projette une bulle protectrice qui emp&#234;che la temp&#233;rature de descendre en dessous de 10 degr&#233;s dans la zone d&#39;effet. La pluie et la neige ne sont jamais plus intenses qu’une l&#233;g&#232;re bruine, le vent ne souffle jamais plus vite qu’un &lt;a class=&quot;pagelink&quot; href=&quot;Climat#Vents_4.html&quot; title=&quot;Les vents&quot;&gt;vent important&lt;/a&gt;, et la &lt;a class=&quot;pagelink&quot; href=&quot;Exploration.html#VISIONLUMIERE&quot; title=&quot;L&amp;#39;exploration&quot;&gt;luminosit&#233;&lt;/a&gt; de la zone ne descent jamais en dessous de faible (bien que les conditions ext&#233;rieures cr&#233;&#233;es par des conditions m&#233;t&#233;orologiques extr&#234;mes, telles que des temp&#234;tes de glace ou de grosses vagues, puisse encore menacer le navire et l&#39;&#233;quipage). Quiconche se repose dans cette zone s&#232;che tr&#232;s vite, et la nourriture ainsi que l&#39;eau conserv&#233;e sur le navire ne p&#233;rime pas naturellement.&lt;br /&gt;&lt;br /&gt;Tant que la lanterne est accroch&#233;e &#224; un navire, ses flammes courent toujours vers l&#39;est, octroyant un bonus de circonstances de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; pour &#233;viter &#224; l&#39;&#233;quipage de se perdre.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Invocation du dieu-h&#233;ros&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;INVOCATIONDUDIEUHEROS&quot; href=&quot;#INVOCATIONDUDIEUHEROS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Origines occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Origins/Origines occultes ; /!\ Traduit par la communaut&#233; /!\&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOO.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;Transmutation&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; 7&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 70 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt; V, S, M (une mixture de vin, de sans d&#39;ext&#233;rieur, et de cendres de c&#232;dre, valant un total de 5 000 PO). F (l&#39;officiant principal doit &#234;tre en p&#233;riode de menstruations). OS (jusqu&#39;&#224; 12)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Test de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; DD 31, 2 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res) DD 31, 2 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (histoire) DD 31, 3 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; contact&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; Jusqu&#39;&#224; 10 cr&#233;atures/niveau de personnage de l&#39;officiant principal concentantes, tous les sujets doivent &#234;tres pr&#233;sents pendant le rituel.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; 14 heures&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jets de sauvegarde&lt;/b&gt; Volont&#233; (inoffensif) ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; oui&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contre coup&lt;/b&gt; l&#39;officiant principal subit 2d6 points de d&#233;g&#226;ts et devient l&#39;objet de l&#39;esprit d&#39;un &#171; dieu &#187; (voir texte).&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; Une cr&#233;ature al&#233;atoire convoquable via un sort de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convocation-De-Monstres-Ix.html&quot; title=&quot;Convocation de monstres IX&quot;&gt;convocation de monstres IX&lt;/a&gt;&lt;/i&gt; appara&#238;t et attaque les participants pendant 9 minutes. &#192; la discretion du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt;, la cr&#233;ature convoqu&#233;e peut poss&#233;der l&#39;arch&#233;type &lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types.html#CREATUREEVOLUEE&quot; title=&quot;Les arch&#233;types&quot;&gt;&#233;volu&#233;e&lt;/a&gt;, &#234;tre accompagn&#233;e d&#39;autres cr&#233;atures, ou les deux.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
Les rituels des habitants du pays perdus qui s’&#233;tendaient avant l’ouverture de la Faille d&#233;moniaque invoquaient et utilisaient beaucoup de leurs innombrables &#171; dieux &#187;, y compris en invoquant des esprits puissants dans les soldats d&#39;un clan pour les investir d’un courage et d’une gr&#226;ce divine pour une bataille &#224; venir. Lors de ce rituel, apr&#232;s une heure de chants, d’appel d’un esprit, de supplications et de contrainte, l&#39;officiant principal se d&#233;place parmi ceux qui doivent &#234;tres investis du pouvoir de l&#39;esprit, peingnant le front des participants avec du sang. Le rituel impr&#232;gne chaque guerrier marqu&#233; d&#39;une passion et d&#39;un courage inhumains, leurs conf&#233;rant un bonus de moral de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jets d&#39;attaque&lt;/a&gt;, aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; et aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html&quot; title=&quot;Les comp&#233;tences&quot;&gt;comp&#233;tence&lt;/a&gt;, ainsi qu&#39;un bonus de moral de +4 aux jets de sauvegarde contre les effets de peur, mais les rendant vuln&#233;rables aux effets qui bannissent les ext&#233;rieurs ou qui infligent plus de d&#233;g&#226;ts aux cr&#233;atures poss&#233;dant le type &lt;a class=&quot;pagelink&quot; href=&quot;Type-Ext&#233;rieur.html&quot; title=&quot;Ext&#233;rieur&quot;&gt;ext&#233;rieur&lt;/a&gt; (comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cercle-Magique-Contre-Le-Chaos.html&quot; title=&quot;Cercle magique contre le Chaos&quot;&gt;cercle magique contre le Chaos&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marteau-Du-Chaos.html&quot; title=&quot;Marteau du chaos&quot;&gt;marteau du Chaos&lt;/a&gt;&lt;/i&gt;). Une cible de ce rituel ne devient pas un ext&#233;rieur ; il gagne seulement une vuln&#233;rabilit&#233; temporaire contre ces effets.&lt;br /&gt;&lt;br /&gt;Pour maintenir la magie de ce rituel, l&#39;officiant principal doit contenir le &#171; dieu &#187; invoqu&#233; dans son corps pendant toute la dur&#233;e du rituel. L&#39;ext&#233;rieur regarde &#224; travers sa chair, lui infligant une douleur intense qui le distrait, et chaque &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;, il a 50% de chances d&#39;&#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;tourdi.html&quot; title=&quot;&#201;tourdi&quot;&gt;&#233;tourdi&lt;/a&gt; par la douleur. Lorsque la dur&#233;e du rituel se termine, l&#39;officiant principal peut rejeter son &#171; dieu &#187; parasite en r&#233;ussissant un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;. S&#39;il le rate, l&#39;esprit reste et continue de lui infliger des souffrances insupportables jusqu&#39;&#224; ce qu&#39;il soit renvoy&#233; &#224; l&#39;aide d&#39;un sort d&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Annulation-Denchantement.html&quot; title=&quot;Annulation d&amp;#39;enchantement&quot;&gt;annulation d&#39;enchantement&lt;/a&gt;&lt;/i&gt;, de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Renvoi.html&quot; title=&quot;Renvoi&quot;&gt;renvoi&lt;/a&gt;&lt;/i&gt;, de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Souhait-Limit&#233;.html&quot; title=&quot;Souhait limit&#233;&quot;&gt;souhait limit&#233;&lt;/a&gt;&lt;/i&gt;, de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Miracle.html&quot; title=&quot;Miracle&quot;&gt;miracle&lt;/a&gt;&lt;/i&gt;, de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;livrance-Des-Mal&#233;dictions.html&quot; title=&quot;D&#233;livrance des mal&#233;dictions&quot;&gt;d&#233;livrance des mal&#233;dictions&lt;/a&gt;&lt;/i&gt;, ou de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Souhait.html&quot; title=&quot;Souhait&quot;&gt;souhait&lt;/a&gt;&lt;/i&gt;. Bannir l&#39;esprit avant la fin de la dur&#233;e du rituel met instantann&#233;ment fin &#224; ses effets.
&lt;/div&gt;
&lt;/td&gt;&lt;td width=&quot;2%&quot;&gt;
&lt;/td&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Invocation fi&#233;lonne&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;INVOCATIONFIELONNE&quot; href=&quot;#INVOCATIONFIELONNE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Livre des Damn&#233;s 2 (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Book of the Damned/Livre des damn&#233;s&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoBD.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Invocation.html&quot; title=&quot;Invocation&quot;&gt;Invocation&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Appel.html&quot; title=&quot;Appel&quot;&gt;appel&lt;/a&gt;) [&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;Mal&lt;/a&gt;] ; &lt;b&gt;Niveau&lt;/b&gt; 9&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 90 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt;  V, G, M (de l&#39;encens rare d&#39;une valeur de 1 000 po), F (un cercle d&#39;invocation et une offrande agr&#233;able au fi&#233;lon, comme un sacrifice ou une &#226;me pi&#233;g&#233;e d&#39;un &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; &#233;gal au FP du fi&#233;lon + 1)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; DD 34, 4 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;re) DD 34, 1 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plan) DD 34, 1 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt; DD 34, 2 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; DD 34, 1 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; courte&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; Un &lt;a class=&quot;pagelink&quot; href=&quot;Type-Ext&#233;rieur.html&quot; title=&quot;Ext&#233;rieur&quot;&gt;ext&#233;rieur&lt;/a&gt; Mauvais&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 heure/niveau de personnage de l&#39;officiant principal&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; aucun (voir texte) ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; non&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; L&#39;officiant principal devient &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puis&#233;&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; Le fi&#233;lon invoqu&#233; s&#39;&#233;chappe de son cercle d&#39;invocation. Ses actions peuvent varier, mais la plupart des fi&#233;lons &#233;chapp&#233;s attaquent avec impatience leurs invocateurs pendant au moins quelques rounds avant de se t&#233;l&#233;porter ou de fuir dans le monde pour entamer un r&#232;gne de terreur.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
Les 20 premi&#232;res minutes du rituel d&#39;invocation fi&#233;lonne consistent &#224; la pr&#233;paration du cercle d&#39;invocation et &#224; l&#39;&#233;criture des noms appropri&#233;s autour du cercle. Cette &#233;tape implique les deux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt; ; si le cercle d&#39;invocation est inscrit de mani&#232;re permanente et a &#233;t&#233; utilis&#233; avec succ&#232;s pour ce rituel dans le pass&#233;, ces tests de Linguistique sont effectu&#233;s avec un bonus de +5. les 30 minutes suivantes du rituel invoquent le fi&#233;lon, impliquant les tests de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissance&lt;/a&gt; et d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; ; si le v&#233;ritable nom du fi&#233;lon est utilis&#233;, ces tests sont effectu&#233;s avec un bonus de +5. Au d&#233;but des 40 derni&#232;res minutes, la forme brumeuse et floue du fi&#233;lon se manifeste dans le cercle, impliquant les quatre derniers tests de &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;. Une fois cette &#233;tape atteinte, le fi&#233;lon se manifeste en chair et en os &#224; la fin du rituel, que le rituel ait r&#233;ussit ou non, bien qu&#39;il ne soit pas capable de blesser les officiants si le rituel est un succ&#232;s.&lt;br /&gt;&lt;br /&gt;Si le rituel est un succ&#232;s, le fi&#233;lon reste dans le &lt;a class=&quot;pagelink&quot; href=&quot;Plans.html&quot; title=&quot;Les plans&quot;&gt;plan Mat&#233;riel&lt;/a&gt; pendant un nombre d&#39;heures &#233;gale au niveau de personnage de l&#39;officiant principal, durant lesquelles ce dernier fait une offrande au fi&#233;lon et exprime sa demande. Si l&#39;alignement de l&#39;officiant principal est le m&#234;me que celui du fi&#233;lon, le fi&#233;lon accepte automatiquement de rendre un service qui ne prend pas plus de temps &#224; effectuer que la dur&#233;e du rituel. Le fi&#233;lon acceptera d&#39;accomplir une t&#226;che plus longue s&#39;il re&#231;oit une offrande suppl&#233;mentaire pour ses services. Chaque offrande donn&#233;e doit &#234;tre d&#39;une valeur &#233;gale ou sup&#233;rieure &#224; celle donn&#233;e lors de l&#39;incantation du rituel et assure la coop&#233;ration du fi&#233;lon pendant un nombre d&#39;heures suppl&#233;mentaires &#233;gal au niveau de personnage de l&#39;officiant principal. &#192; la discr&#233;tion de l&#39;officiant principal, le d&#233;but de ces heures suppl&#233;mentaires peut &#234;tre retard&#233; jusqu&#39;&#224; ce qu&#39;une certaine situation se produise, auquel cas le fi&#233;lon r&#233;appara&#238;t imm&#233;diatement dans son cercle d&#39;invocation d&#39;origine et peut imm&#233;diatement partir pour terminer sa t&#226;che. Si le v&#233;ritable nom du fi&#233;lon a &#233;t&#233; utilis&#233; pendant le rituel, toutes ces p&#233;riodes de temps normalement mesur&#233;es en heures (y compris la dur&#233;e initiale du rituel) sont mesur&#233;es en jours.&lt;br /&gt;&lt;br /&gt;Si, &#224; tout moment pendant la servitude du fi&#233;lon, l&#39;officiant principal est tu&#233; ou si le cercle d&#39;invocation d&#39;origine est endommag&#233;, le fi&#233;lon a droit &#224; un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour &#233;chapper au pouvoir du rituel. S&#39;il r&#233;ussit, le fi&#233;lon n&#39;est plus tenu d&#39;accomplir la t&#226;che qui lui a &#233;t&#233; ordonn&#233;e et peut rester sur le plan Mat&#233;riel aussi longtemps qu&#39;il le souhaite.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Manifestation &#233;vidente&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MANIFESTATIONEVIDENTE&quot; href=&quot;#MANIFESTATIONEVIDENTE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Livre des Damn&#233;s 2 (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Book of the Damned/Livre des damn&#233;s&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoBD.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Divination.html&quot; title=&quot;Divination&quot;&gt;Divination&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; 9&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 90 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt;  G, F (Le &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Livre-Des-Damn&#233;s.html&quot; title=&quot;Livre des damn&#233;s&quot;&gt;livre des damn&#233;s&lt;/a&gt;&lt;/i&gt; int&#233;gral ou le &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Livre-Des-Damn&#233;s-Diabolique.html&quot; title=&quot;Livre des damn&#233;s diabolique&quot;&gt;livre des damn&#233;s diabolique&lt;/a&gt;&lt;/i&gt;)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plans) DD 33, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Linguistique.html&quot; title=&quot;Linguistique&quot;&gt;Linguistique&lt;/a&gt; DD 33, 4 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; DD 33, 2 succ&#232;s (ces tests subissent un malus de -4 si le &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Livre-Des-Damn&#233;s-Diabolique.html&quot; title=&quot;Livre des damn&#233;s diabolique&quot;&gt;livre des damn&#233;s diabolique&lt;/a&gt;&lt;/i&gt; est utilis&#233; comme focalisateur)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; contact&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; instantan&#233;e&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; aucun ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; non&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; L&#39;officiant principal devient &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puis&#233;&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; Le v&#233;ritable nom de l&#39;officiant principal appara&#238;t quelque part dans un document al&#233;atoire d&#39;une biblioth&#232;que situ&#233;e quelque part sur Abaddon, dans les Abysses ou l&#39;Enfer. Une fois par an, &#224; un moment choisi par le MJ (invariablement &#224; un moment qui ne convient pas &#224; l&#39;officiant principal), il y a un pourcentage de chance &#233;gal au nombre de fois o&#249; le v&#233;ritable nom de l&#39;officiant principal est apparu dans un tel document (1% par tentative d&#39;accomplir la manifestation &#233;vidente) qu&#39;une autre force d&#233;couvre le v&#233;ritable nom de l&#39;officiant principal et l&#39;utilise. En r&#232;gle g&#233;n&#233;rale, cela se traduit par une invocation de l&#39;officiant principal ailleurs via une magie puissante pour effectuer des services ; &#224; la discr&#233;tion du MJ, cela peut &#234;tre jou&#233;, ou l&#39;officiant principal peut simplement retourner &#224; son point d&#39;origine 4d6 heures plus tard avec 1d6 de &lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;Affaiblissement temporaire (Ext ou Sur)&quot;&gt;diminution permanente&lt;/a&gt; de caract&#233;ristique, 1d3 de &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveaux n&#233;gatifs&lt;/a&gt;, une mal&#233;diction &#233;trange ou une autre affliction mais sans aucun souvenir de la fa&#231;on dont cette affliction est apparue. Retirer son nom de ces lieux ne peut &#234;tre accompli que via une qu&#234;te significative.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
Lorsque l&#39;officiant principal commence le rituel de manifestation &#233;vidente, il doit avoir &#224; l&#39;esprit un type sp&#233;cifique de fi&#233;lon dont il veux apprendre le v&#233;ritable nom. S&#39;il cherche &#224; apprendre le v&#233;ritable nom d&#39;un individu fi&#233;lon sp&#233;cifique ou unique, le DD des tests de comp&#233;tence du rituel augmente de 5, et s&#39;il cherche &#224; apprendre le v&#233;ritable nom d&#39;un demi-divin ou d&#39;une quasi-divinit&#233; fi&#233;lonne, ils augmentent de 10 (dans ce dernier cas, le v&#233;ritable nom du demi-dieu ou de la quasi-divinit&#233; fi&#233;lonne change une fois que l&#39;officiant principal l&#39;a appris, donc cette information n&#39;est utile qu&#39;une seule fois, et en cas d&#39;&#233;chec, le demi-dieu ou la quasi-divinit&#233; apprend le v&#233;ritable nom de l&#39;officiant principal &#224; la place). Une fois que le v&#233;ritable nom d&#39;une cr&#233;ature est divulgu&#233; par la manifestation de la liste du &lt;i&gt;Livre des damn&#233;s&lt;/i&gt;, l&#39;officiant principal peut utiliser cette information comme il l&#39;entend, mais l&#39;abus de l&#39;information aura probablement des r&#233;percussions. Par exemple, un officiant principal qui acquiert de la r&#233;putation en r&#233;pandant le v&#233;ritable nom d&#39;un fi&#233;lon puissant pourrait se retrouver pourchass&#233; par un large &#233;ventail de fi&#233;lons puissants, tous d&#233;sireux de voir l&#39;officiant principal d&#233;truit. De telles repr&#233;sailles ne d&#233;coulent pas d&#39;une sorte de d&#233;votion familiale envers le fi&#233;lon incommod&#233;, mais purement de l&#39;autod&#233;fense, car qui peut dire quel nom de fi&#233;lon pourrait ensuite &#234;tre rendu public par un officiant aussi n&#233;gligent ?
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Ouverture du troisi&#232;me œil&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;OUVERTUREDUTROISIEMEOEIL&quot; href=&quot;#OUVERTUREDUTROISIEMEOEIL&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;Transmutation&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; 5&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d’incantation&lt;/b&gt; 50 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt; V, G, M (encens), OS (jusqu’&#224; 12)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res) DD 34, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plans) DD 34, 1 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; DD 34, 1 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; contact&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; officiants principal et secondaires&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 jour (D)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; Vigueur annule (inoffensif) ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; oui (inoffensif )&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; tous les officiants subissent 2d6 points de d&#233;g&#226;ts.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; tous les officiants re&#231;oivent un &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveau n&#233;gatif&lt;/a&gt; temporaire (DD = 16 + bonus de Charisme de l’officiant principal pour l’&#233;liminer apr&#232;s la premi&#232;re journ&#233;e) et l’officiant principal est victime d’une version particuli&#232;rement virulente de la bouillecr&#226;ne (DD 17 ; 2 JdS ; 1d4 Int ; 1/jour).&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
Les officiants c&#233;l&#233;brant ce rituel harmonisent leur psych&#233; lors d’une c&#233;r&#233;monie de m&#233;ditation et de r&#233;citations. Les officiants ne disposant pas de niveaux dans une classe occulte disposent des avantages suivants.&lt;br /&gt;&lt;br /&gt;Chaque officiant peut choisir une astuce de la &lt;a class=&quot;pagelink&quot; href=&quot;Sorts-De-Psychiste.html&quot; title=&quot;Liste des sorts de psychiste&quot;&gt;liste de sorts du psychiste&lt;/a&gt; et une astuce de plus par tranche de 5 niveaux de personnage (pour un maximum de 5 astuces au niveau 20). Ils peuvent les lancer &#224; volont&#233;.&lt;br /&gt;&lt;br /&gt;Si un officiant est form&#233; dans une comp&#233;tence dot&#233;e d’une version occulte, il peut utiliser cette version occulte.&lt;br /&gt;&lt;br /&gt;Les officiants poss&#233;dant des niveaux dans une classe occulte obtiennent les avantages suivants.&lt;br /&gt;&lt;br /&gt;Si un officiant est form&#233; dans une comp&#233;tence dot&#233;e d’une &lt;a class=&quot;pagelink&quot; href=&quot;Extensions-De-Comp&#233;tences-Occultes.html&quot; title=&quot;Extensions de comp&#233;tences occultes&quot;&gt;version occulte&lt;/a&gt;, il gagne un bonus d’intuition de +4 aux tests quand il utilise la version occulte.&lt;br /&gt;&lt;br /&gt;Si un officiant n’est pas form&#233; dans une comp&#233;tence dot&#233;e d’une version occulte, il peut tout de m&#234;me utiliser cette version occulte.&lt;br /&gt;&lt;br /&gt;Chaque officiant participant au rituel peut dissiper les effets de l’incantation l’affectant personnellement, sans que cela influe sur les autres.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Premi&#232;re apoth&#233;ose&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PREMIERAPOTHEOSE&quot; href=&quot;#PREMIERAPOTHEOSE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Livre des Damn&#233;s 2 (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Book of the Damned/Livre des damn&#233;s&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoBD.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;Transmutation&lt;/a&gt; [&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;Mal&lt;/a&gt;] ; &lt;b&gt;Niveau&lt;/b&gt; 4&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 4 heures&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt;  V, G, M (de l&#39;encens exotique d&#39;une valeur de 500 po)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; DD 18, 2 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plan ou religion) DD 18, 2 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; personnelle&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; officiant principal&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; instantan&#233;e&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; aucun ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; non&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; L&#39;officiant principal subit 4d6 points de d&#233;g&#226;ts et devient &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puis&#233;&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; L&#39;officiant principal devient &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Inconscient.html&quot; title=&quot;Inconscient&quot;&gt;inconscient&lt;/a&gt; pendant 2d4 heures et doit attendre 1 an avant de tenter la premi&#232;re apoth&#233;ose une nouvelle fois.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
Le premier rituel est le plus simple et ne requiert rien de plus que l&#39;alignement de l&#39;officiant principal devienne Loyal Mauvais, Neutre Mauvais ou Chaotique Mauvais (selon le type de fi&#233;lon que l&#39;utilisateur souhaite devenir). Pour se pr&#233;parer au rituel, l&#39;officiant pricncipal doit entreprendre des actes de nature ignobles et destructeur au cours d&#39;une ann&#233;e. Le lanceur de sorts confie alors son &#226;me &#224; Abaddon, aux Abysses ou &#224; l&#39;Enfer, m&#234;me s&#39;il ne termine jamais les rituels suivants. L&#39;officiant principal doit s&#233;lectionner un fi&#233;lon puissant &#224; cet instant pour servir de protecteur d&#233;moniaque. Les actes que l&#39;officiant principal doit entreprendre peuvent varier, mais ils doivent &#234;tre d&#39;une nature qui repr&#233;sente et honore les domaines d&#39;int&#233;r&#234;t du protecteur d&#233;moniaque choisi ; ces actes sont destin&#233;s &#224; attirer l&#39;attention du protecteur, apr&#232;s tout. M&#234;me un officiant principal qui commence le rituel de transformation avec un alignement Mauvais doivent subir cette &#233;tape du rituel, ne serait-ce que pour s&#233;lectionner un protecteur fi&#233;lon. &lt;br /&gt;&lt;br /&gt;Lors du jour exact suivant cette ann&#233;e d&#39;actes vicieux, l&#39;officiant principal doit effectuer le rituel de 4 heures de la premi&#232;re apoth&#233;ose pour consacrer correctement son ann&#233;e pr&#233;c&#233;dente au nom du protecteur choisi. Une fois qu&#39;il a r&#233;ussi la premi&#232;re apoth&#233;ose, il devient &#233;ligible pour entreprendre la &lt;a class=&quot;pagelink&quot; href=&quot;Exemples-De-Rituels-Occultes.html#DEUXIEMEAPOTHEOSE&quot; title=&quot;Exemples de rituels occultes&quot;&gt;deuxi&#232;me apoth&#233;ose&lt;/a&gt;. 
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Protection psychique&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PROTECTIONPSYCHIQUE&quot; href=&quot;#PROTECTIONPSYCHIQUE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Abjuration.html&quot; title=&quot;Abjuration&quot;&gt;Abjuration&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; 6&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d’incantation&lt;/b&gt; 60 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt; V, G, M (poussi&#232;re de diamant d’une valeur de 500 po), F (miroirs en mithral d’une valeur de 10 000 po et une lanterne allum&#233;e)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; DD 33, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res) DD 33, 3 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; contact&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; 1 cr&#233;ature&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 jour/niveau de personnage de l’officiant&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; Volont&#233; annule (inoffensif ) ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; oui (inoffensif )&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; l’officiant subit 2d6 points de d&#233;g&#226;ts et se trouve &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puis&#233;&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; l’officiant re&#231;oit un &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveau n&#233;gatif&lt;/a&gt; permanent.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
L’officiant doit commencer cette incantation &#224; l’aube ou au cr&#233;puscule, dans une salle sans fen&#234;tre, en compagnie de la cible d&#233;sir&#233;e (qui n’est pas l’officiant), entour&#233; des miroirs en mithral tourn&#233;s vers l’int&#233;rieur de la pi&#232;ce. &#192; la fin de l’incantation, l’officiant souffle une lanterne avec la poussi&#232;re de diamant et reste dans le noir avec la cible. Il doit toucher la cible dans les t&#233;n&#232;bres avant de sortir de la pi&#232;ce. Ensuite, pendant un nombre de jours &#233;gal au niveau de personnage de l’officiant, la cible b&#233;n&#233;ficie d’un bonus de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les sorts et pouvoirs psychiques mais elle ne peut pas utiliser de capacit&#233; magique psychique, lancer de sort psychique ni utiliser la &lt;a class=&quot;pagelink&quot; href=&quot;La-Magie-Psychique.html&quot; title=&quot;La magie psychique&quot;&gt;magie psychique&lt;/a&gt;. Elle ne peut pas non plus lancer un &lt;a class=&quot;pagelink&quot; href=&quot;Duels-Psychiques.html&quot; title=&quot;Les duels psychiques&quot;&gt;duel psychique&lt;/a&gt; ni &#234;tre entra&#238;n&#233;e dans un tel duel.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Quatri&#232;me apoth&#233;ose&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;QUATRIEMEAPOTHEOSE&quot; href=&quot;#QUATRIEMEAPOTHEOSE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Livre des Damn&#233;s 2 (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Book of the Damned/Livre des damn&#233;s&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoBD.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;Transmutation&lt;/a&gt; [&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;Mal&lt;/a&gt;] ; &lt;b&gt;Niveau&lt;/b&gt; 9&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 9 heures&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt;  V, G, M (sacrifice vivant significatif de &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; 9 ou plus) ; OS (jusqu’&#224; 20)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; DD 31, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plans)  DD 31, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion)  DD 31, 3 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; personnelle&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; officiant principal&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; instantan&#233;e&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; aucun ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; non&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; Tous les officiants subissent 4d6 points de d&#233;g&#226;ts et deviennent &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puis&#233;s&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; Tous les officiants sont tu&#233;s.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
Pour ceux qui souhaitent aller plus loin que de simplement devenir un &lt;a class=&quot;pagelink&quot; href=&quot;Demi-Fi&#233;lon,-Arch&#233;type.html&quot; title=&quot;Demi-fi&#233;lon, arch&#233;type&quot;&gt;demi-fi&#233;lon&lt;/a&gt;, un quatri&#232;me rituel existe. Le seigneur fi&#233;lon de l&#39;officiant principal n&#39;accorde aucune vision ou conseil pour commencer ce rituel ; l&#39;officiant principal doit prendre sur lui d&#39;honorer son protecteur d&#39;une mani&#232;re appropri&#233;e aux int&#233;r&#234;ts et aux th&#232;mes de ce fi&#233;lon. Une fois par an, &#224; l&#39;anniversaire du jour o&#249; le l&#39;officiant principal a termin&#233; la &lt;a class=&quot;pagelink&quot; href=&quot;Exemples-De-Rituels-Occultes.html#TROISIEMEAPOTHEOSE&quot; title=&quot;Exemples de rituels occultes&quot;&gt;troisi&#232;me apoth&#233;ose&lt;/a&gt;, il peut effectuer une c&#233;r&#233;monie sp&#233;ciale qui raconte ses r&#233;alisations au cours de l&#39;ann&#233;e &#233;coul&#233;e et se termine par un sacrifice important (consistant g&#233;n&#233;ralement &#224; sacrifier un membre important d&#39;une religion ennemie, ou un ext&#233;rieur Loyal ou Bon ; dans les deux cas, le sacrifice doit &#234;tre au moins FP 9). Si ce rituel est un succ&#232;s, l&#39;officiant principal se transforme en un fi&#233;lon &#224; part enti&#232;re : il perd tous les avantages de sa race pr&#233;c&#233;dente et de l&#39;arch&#233;type demi-fi&#233;lon mais peut imm&#233;diatement appliquer tous ses niveaux de classe &#224; sa nouvelle race fi&#233;lonne (par exemple, un &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerrier&lt;/a&gt; 10 pourrait devenir un &lt;a class=&quot;pagelink&quot; href=&quot;Vrock.html&quot; title=&quot;D&#233;mon, Vrock&quot;&gt;vrock&lt;/a&gt; guerrier 10). Le type de fi&#233;lon en lequel il se transforme d&#233;pend &#224; la fois de la nature de son protecteur fi&#233;lon choisi et de la discr&#233;tion du MJ, mais il ne devrait g&#233;n&#233;ralement pas avoir un nombre total de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;d&#233;s de vie&lt;/a&gt; sup&#233;rieur au double de ses d&#233;s de vie d&#39;origine. L&#39;officiant principal n&#39;a g&#233;n&#233;ralement qu&#39;une seule chance pour le quatri&#232;me apoth&#233;ose, car un &#233;chec entra&#238;ne sa mort ; cependant, si il est ramen&#233;e &#224; la vie, il peut tenter la quatri&#232;me apoth&#233;ose une nouvelle fois.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Recherche d&#39;intuition astrale&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;RECHERCHEDINTUITIONASTRALE&quot; href=&quot;#RECHERCHEDINTUITIONASTRALE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Divination.html&quot; title=&quot;Divination&quot;&gt;Divination&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; 6&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d’incantation&lt;/b&gt; 60 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt; V, G, M (des chandelles faites de cire d’abeille pure, en nombre &#233;gal au nombre de plan&#232;tes en conjonction lors du rituel), F (une cha&#238;ne en mithral d’une valeur de 5 000 po), OS (jusqu’&#224; 8)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res) DD 31, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plans) DD 31, 3 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; officiant principal&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 heure/niveau de personnage de l’officiant principal&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; l’officiant principal est muet pendant une semaine (si le rituel &#233;choue, cet effet se produit apr&#232;s la p&#233;riode d’effet de la &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;bilit&#233;.html&quot; title=&quot;D&#233;bilit&#233;&quot;&gt;d&#233;bilit&#233;&lt;/a&gt;&lt;/i&gt;).&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; les valeurs d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; de l’officiant principal tombent &#224; 1 et il est victime d’une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;bilit&#233;.html&quot; title=&quot;D&#233;bilit&#233;&quot;&gt;d&#233;bilit&#233;&lt;/a&gt;&lt;/i&gt; pendant 24 heures.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
Ce rituel se c&#233;l&#232;bre obligatoirement de nuit, quand au moins trois plan&#232;tes sont en conjonction et en vue des officiants. Ces derniers doivent accomplir ce rituel au sommet d’une colline, d’une montagne ou d’un autre point culminant naturel. L’officiant principal est tout d’abord envelopp&#233; dans les cha&#238;nes servant de focalisateur puis il faut allumer les chandelles dispos&#233;es comme les plan&#232;tes en conjonction. L’officiant principal s’assoit dans un silence complet, concentr&#233; sur la lumi&#232;re des chandelles, tandis que les autres se placent en cercle et entonnent une incantation occulte. Si le rituel se solde par un succ&#232;s, l’esprit de l’officiant principal erre librement dans le &lt;a class=&quot;pagelink&quot; href=&quot;Plans-&#201;sot&#233;riques.html#PLANASTRAL&quot; title=&quot;Plans &#233;sot&#233;riques&quot;&gt;plan Astral&lt;/a&gt; et peut poser une question par heure de vagabondage. Les esprits du plan Astral lui r&#233;pondent sinc&#232;rement mais il n’y a que 60 % de chances qu’ils aient la r&#233;ponse &#224; la question pos&#233;e (ce pourcentage peut &#234;tre plus bas ou plus &#233;lev&#233;, au gr&#233; du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt;, en fonction de la nature de l’information recherch&#233;e). Si les esprits ignorent la r&#233;ponse, ils l’avouent &#224; l’officiant plut&#244;t que d’essayer de le tromper.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Rugissement tranquille de l’esprit du paon&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;RUGISSEMENTTRANQUILLEDELESPRITDUPAON&quot; href=&quot;#RUGISSEMENTTRANQUILLEDELESPRITDUPAON&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Origines occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Origins/Origines occultes ; /!\ Traduit par la communaut&#233; /!\&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOO.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Abjuration.html&quot; title=&quot;Abjuration&quot;&gt;Abjuration&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; 8&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 80 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt; V, S, M (une plume de paon et de la poudre de malachite valant 5000 PO). OS (jusqu&#39;&#224; 8)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res) DD 32, 2 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion) DD 32, 2 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; (chant ou percussions) DD 32, 4 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; contact&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; Une structure ou une zone de 9m de rayon&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; 8 jours&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jets de sauvegarde&lt;/b&gt; Volont&#233;, annule ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; oui&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contre coup&lt;/b&gt; Tous les officiants suvissent 2d6 points de d&#233;g&#226;ts et se retrouvent &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puis&#233;s&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; Tous les officiants subissent un &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveau n&#233;gatif&lt;/a&gt; et ne peuvent plus utiliser la &lt;a class=&quot;pagelink&quot; href=&quot;La-Magie-Psychique.html&quot; title=&quot;La magie psychique&quot;&gt;magie psychique&lt;/a&gt; et les &lt;a class=&quot;pagelink&quot; href=&quot;Extensions-De-Comp&#233;tences-Occultes.html&quot; title=&quot;Extensions de comp&#233;tences occultes&quot;&gt;extensions de comp&#233;tences occultes&lt;/a&gt; pendant 1 semaine&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
L&#39;officiant principal commence par utiliser une plume de paon pour former un cercle avec la poudre de malachite autour d&#39;un b&#226;timent ou d&#39;un site sacr&#233; et fait appel &#224; des murmures feutr&#233;s -le ch&#226;timent discret du myst&#233;rieux Esprit du Paon- pour effacer les magies invasives qui r&#233;v&#232;lent les secrets. Quiconque tente de lancer un sort ou un pouvoir magique de &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Divination.html&quot; title=&quot;Divination&quot;&gt;divination&lt;/a&gt; ou d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Enchantement.html&quot; title=&quot;Enchantement&quot;&gt;enchantement&lt;/a&gt; qui d&#233;tecte les pens&#233;es ou oblige &#224; dire la v&#233;rit&#233; dans la zone d&#39;effet, ou qui cible la zone d&#39;effet avec un sort de d&#233;tection comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Scrutation.html&quot; title=&quot;Scrutation&quot;&gt;scrutation&lt;/a&gt;&lt;/i&gt; doit d&#39;abord r&#233;ussir un test de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;. S&#39;il le rate, le lanceur du sorts perd son sort et subit 1d6+8 points de d&#233;g&#226;ts alors que l&#39;Esprit du Paon retourne sa magie contre lui. S&#39;il le r&#233;ussit, le sort fonctionne normalement. Un lanceur de sorts qui r&#233;ussit ce &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; est immunis&#233; contre les effets de rituel pendant 24 heures ou jusqu&#39;&#224; ce qu&#39;il quitte et r&#233;entre dans la zone.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Sceau des poup&#233;es dansantes&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;SCEAUDESPOUPEESDANSANTES&quot; href=&quot;#SCEAUDESPOUPEESDANSANTES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Origines occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Origins/Origines occultes ; /!\ Traduit par la communaut&#233; /!\&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOO.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Invocation.html&quot; title=&quot;Invocation&quot;&gt;Invocation&lt;/a&gt; ; &lt;b&gt;Niveau&lt;/b&gt; 6&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 6 heures&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt; V, S, M (un sceau de bronze orn&#233; d&#39;acacia et de r&#233;sine de quartz valant 500 PO). OS (jusqu&#39;&#224; 4)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res) DD 33, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plans) DD 33, 3 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; contact&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; 1 an&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jets de sauvegarde&lt;/b&gt; Volont&#233;, annule ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; oui&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contre coup&lt;/b&gt; Tous les officiants prennent 1 &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveau n&#233;gatif&lt;/a&gt; temporaire&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; L&#39;ext&#233;rieur en train d&#39;&#234;tre li&#233; est lib&#233;r&#233; et attaque.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
Con&#231;u pour fabriquer une cr&#233;ature artificielle antique consid&#233;r&#233;e comme un pr&#233;curseur des premiers golems, ce rituel n&#233;cessite des heures de calculs laborieux, de r&#233;citations et de concentration pour lier un ext&#233;rieur &#233;l&#233;mentaire (une cr&#233;ature avec le sous-type &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-&#201;l&#233;mentaire.html&quot; title=&quot;&#201;l&#233;mentaire (sous-type)&quot;&gt;&#233;l&#233;mentaire&lt;/a&gt; ou un g&#233;nie) dans une prison de bronze, en exploitant la force de vie vibrante de l&#39;ext&#233;rieur pour animer un objet. Le sceau doit d&#233;j&#224; &#234;tre appos&#233; sur l&#39;objet &#224; animer (g&#233;n&#233;ralement un mannequin ou une statue), et l&#39;ext&#233;rieur doit &#234;tre dans la zone du rituel et contenu (via un sort d’&lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Entrave.html&quot; title=&quot;Entrave&quot;&gt;entrave&lt;/a&gt;&lt;/i&gt;, un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cercle-Magique.html&quot; title=&quot;Cercle magique&quot;&gt;cercle magique&lt;/a&gt;&lt;/i&gt; ou une magie similaire). Apr&#232;s la r&#233;ussite du rituel, l&#39;ext&#233;rieur est forc&#233; &#224; servir loyalement dans le sceau pendant un an et un jour, perdant acc&#232;s &#224; la plupart de ses pouvoirs et de ses souvenirs et traitant l&#39;objet auquel le sceau est appos&#233; comme son nouveau corps. Ces serviteurs anim&#233;s &#233;taient le plus souvent utilis&#233;s comme gardiens ou gardes du corps, mais servaient aussi parfois d&#39;assassins.&lt;br /&gt;&lt;br /&gt;Ce sceau peut &#234;tre utilis&#233; pour cr&#233;er un &lt;a class=&quot;pagelink&quot; href=&quot;Objet-Anim&#233;.html&quot; title=&quot;Objet anim&#233;&quot;&gt;objet anim&#233;&lt;/a&gt; ou &#234;tre combin&#233; avec le don &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Cr&#233;atures-Artificielles.html&quot; title=&quot;Cr&#233;ation de cr&#233;atures artificielles&quot;&gt;Cr&#233;ation de cr&#233;atures artificielles&lt;/a&gt; ; le sceau remplace toutes les conditions de sort dans la cr&#233;ation de la cr&#233;ature, mais pas le temps n&#233;cessaire ou le co&#251;t en mat&#233;riaux. Puisque le rituel supprime une grande partie de la puissance et du libre arbitre de l&#39;ext&#233;rieur, ce dernier doit avoir deux fois plus de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;D&#233;s de Vie&lt;/a&gt; que la cr&#233;ature artificielle cr&#233;&#233;e. Apr&#232;s 1 an, la cr&#233;ature artificielle devient inerte, mais elle peut &#234;tre r&#233;anim&#233; en ex&#233;cutant &#224; nouveau le rituel sans frais suppl&#233;mentaires au-del&#224; de la pr&#233;paration d&#39;un nouveau sceau.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Sceau d&#39;&#233;vitement&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;SCEAUDEVITEMENT&quot; href=&quot;#SCEAUDEVITEMENT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Enchantement.html&quot; title=&quot;Enchantement&quot;&gt;Enchantement&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Coercition.html&quot; title=&quot;Coercition&quot;&gt;coercition&lt;/a&gt;) ; &lt;b&gt;Niveau&lt;/b&gt; 4&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d’incantation&lt;/b&gt; 40 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt; V, M (un morceau de charbon de sorbier), F (un petit miroir en argent d’une valeur de 50 po)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; DD 30, 1 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (exploration souterraine) DD 30, 3 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; contact&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; 1 porte de donjon&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; 8 heures&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; Volont&#233;, annule (inoffensif, objet) ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; oui (inoffensif, objet)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; le lanceur subit 4d6 points de d&#233;g&#226;ts.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; la porte s’ouvre en grand et l’officiant ne peut plus la fermer pendant 24 heures, d’aucune mani&#232;re, &#224; moins d’un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Souhait-Limit&#233;.html&quot; title=&quot;Souhait limit&#233;&quot;&gt;souhait limit&#233;&lt;/a&gt;&lt;/i&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
L’officiant commence par placer un miroir d’un c&#244;t&#233; de la porte et trace des symboles occultes de l’autre c&#244;t&#233;. Ils correspondent &#224; un type de cr&#233;ature de la liste des &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENNEMIJURE&quot; title=&quot;Le r&#244;deur&quot;&gt;ennemis jur&#233;s&lt;/a&gt; du r&#244;deur. &#192; la fin du rituel, les cr&#233;atures du type ou sous-type choisi ne peuvent plus ouvrir, toucher ni manipuler la porte par magie ni d’aucune mani&#232;re (sans &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; et sans possibilit&#233; d’appliquer la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;RM&quot;&gt;r&#233;sistance &#224; la magie&lt;/a&gt;). Une porte de donjon ne peut b&#233;n&#233;ficier que d’un seul sceau d’&#233;vitement &#224; la fois.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Structure voil&#233;e&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;STRUCTUREVOILEE&quot; href=&quot;#STRUCTUREVOILEE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Aventures occultes (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Occult Adventures/Aventures occultes&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoOA.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Illusion.html&quot; title=&quot;Illusion&quot;&gt;Illusion&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Hallucination.html&quot; title=&quot;Hallucination&quot;&gt;hallucination&lt;/a&gt;) ; &lt;b&gt;Niveau&lt;/b&gt; 8&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d’incantation&lt;/b&gt; 80 minutes&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt; V, G, M (2 litres d’eau venant d’une source fra&#238;che et une potion d’invisibilit&#233;), F (deux cruches en mithral et deux goupillons en or, d’une valeur de 25 000 po au total), OS (au moins 4 et jusqu’&#224; 12)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; DD 32, 2 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (nature ou folklore local ; voir plus bas) DD 32, 4 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt; DD 32, 2 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; courte (7,50 m + 1,50 m/niveau de personnage de l’officiant principal)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Zone&lt;/b&gt; un cube de 6 m de c&#244;t&#233;/niveau de personnage de l’officiant principal&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; permanent (D)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; Volont&#233; pour percer &#224; jour (en cas d’interaction) ;&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; non&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; l’officiant principal re&#231;oit un &lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;niveau n&#233;gatif&quot;&gt;niveau n&#233;gatif&lt;/a&gt; permanent.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; aucun des officiants ne peut profiter des effets b&#233;n&#233;fiques d’un sort d’&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Hallucination.html&quot; title=&quot;Hallucination&quot;&gt;hallucination&lt;/a&gt; (comme &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt;) pendant 1 an (c’est un effet de mal&#233;diction qui peut se dissiper avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;livrance-Des-Mal&#233;dictions.html&quot; title=&quot;D&#233;livrance des mal&#233;dictions&quot;&gt;d&#233;livrance des mal&#233;dictions&lt;/a&gt;&lt;/i&gt; ou un effet similaire).&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
L’officiant principal commence le rituel en versant l’eau de source fra&#238;che dans l’une des cruches et la potion d’invisibilit&#233; dans l’autre. Il m&#233;lange ensuite les composantes des deux cruches en versant l’eau dans la cruche qui contient la potion et transf&#232;re ensuite le m&#233;lange dans la cruche qui contenait l’eau au d&#233;part. Il r&#233;p&#232;te ce transfert &#224; six reprises avant de tendre l’une des cruches &#224; l’un des officiants secondaires. Dans le silence le plus complet, l’officiant principal et l’officiant secondaire qu’il a choisi utilisent les goupillons pour asperger de ce m&#233;lange le b&#226;timent ou la structure qu’ils veulent voiler. Leur cible ne doit pas &#234;tre plus grande que la zone d’effet du rituel. Si la cible est un &#233;l&#233;ment naturel, les officiants doivent effectuer des tests de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (nature) lors du rituel. Si c’est un &#233;l&#233;ment urbain, ils doivent faire des tests de &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (folklore local).&lt;br /&gt;&lt;br /&gt;Une fois le rituel termin&#233; avec succ&#232;s, le b&#226;timent est voil&#233; : il semble que la zone ne contient rien d’autre que son d&#233;cor naturel ou urbain. Tous les officiants ayant particip&#233; au rituel distinguent encore les contours de la structure et peuvent interagir normalement avec elle. L’officiant principal peut permettre &#224; un maximum de dix cr&#233;atures par jour, qu’il doit toucher, de voir les contours du b&#226;timent pendant une p&#233;riode de 24 heures.
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Troisi&#232;me apoth&#233;ose&lt;div style=&quot;float:right;&quot;&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TROISIEMEAPOTHEOSE&quot; href=&quot;#TROISIEMEAPOTHEOSE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Livre des Damn&#233;s 2 (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Book of the Damned/Livre des damn&#233;s&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoBD.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Transmutation.html&quot; title=&quot;Transmutation&quot;&gt;Transmutation&lt;/a&gt; [&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;Mal&lt;/a&gt;] ; &lt;b&gt;Niveau&lt;/b&gt; 6&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 6 heures&lt;/li&gt;&lt;li&gt;&lt;b&gt;Composantes&lt;/b&gt;  V, G, M (de l&#39;encens exotique d&#39;une valeur de 2 000 po, ach&#232;vement pr&#233;alable de la qu&#234;te sp&#233;ciale); OS (jusqu’&#224; 8)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tests de comp&#233;tence&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; DD 28, 3 succ&#232;s ; &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (plans ou religion) DD 28, 3 succ&#232;s&lt;/li&gt;&lt;li&gt;&lt;b&gt;Port&#233;e&lt;/b&gt; personnelle&lt;/li&gt;&lt;li&gt;&lt;b&gt;Cible&lt;/b&gt; officiant principal&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dur&#233;e&lt;/b&gt; instantan&#233;e&lt;/li&gt;&lt;li&gt;&lt;b&gt;Jet de sauvegarde&lt;/b&gt; aucun ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; non&lt;/li&gt;&lt;li&gt;&lt;b&gt;Contrecoup&lt;/b&gt; Tous les officiants subissent 4d6 points de d&#233;g&#226;ts et deviennent &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puis&#233;s&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;&#201;chec&lt;/b&gt; Tous les officiants sont r&#233;duits a -1 &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;point de vie&quot;&gt;pv&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Effet&lt;/div&gt;
&#192; un moment donn&#233; apr&#232;s que le l&#39;officiant principal a contact&#233; son protecteur fi&#233;lon (g&#233;n&#233;ralement apr&#232;s avoir r&#233;ussi le &lt;a class=&quot;pagelink&quot; href=&quot;Exemples-De-Rituels-Occultes.html#DEUXIEMEAPOTHEOSE&quot; title=&quot;Exemples de rituels occultes&quot;&gt;deuxi&#232;me rituel&lt;/a&gt;, mais parfois avant), le fi&#233;lon envoie &#224; l&#39;officiant principal une vision d&#39;une t&#226;che qu&#39;il doit accomplir (comme lib&#233;rer un &lt;a class=&quot;pagelink&quot; href=&quot;Type-Ext&#233;rieur.html&quot; title=&quot;Ext&#233;rieur&quot;&gt;ext&#233;rieur&lt;/a&gt; Mauvais retenu prisonnier d&#39;une sur le plan Mat&#233;riel ou assassiner un puissant pr&#234;tre d&#39;une religion d&#39;alignement Bon). Cette t&#226;che est g&#233;n&#233;ralement importante pour le fi&#233;lon, et dans de nombreux cas, c&#39;est une t&#226;che que l&#39;officiant principal n&#39;a aucun espoir d&#39;accomplir jusqu&#39;&#224; ce qu&#39;il devienne plus puissant. Il n&#39;y a pas de limite de temps pour que l&#39;officiant principal accomplisse cette t&#226;che, mais il doit entretenir une d&#233;votion hebdomadaire &#224; son protecteur fi&#233;lon sous la forme d&#39;un culte r&#233;gulier et d&#39;atrocit&#233;s continues au nom du fi&#233;lon. Des offrandes br&#251;l&#233;es suppl&#233;mentaires au fi&#233;lon, des agressions contre des innocents et des trahisons d&#39;alli&#233;s sont des choix populaires. Une fois la tache assign&#233;e compl&#233;t&#233;e, l&#39;officiant principal peux effectuer la troisi&#232;me apoth&#233;ose. Contrairement aux premier et deuxi&#232;me rituels, la troisi&#232;me apoth&#233;ose autorise le soutien d&#39;officiants secondaires, mais comporte un risque d&#39;&#233;chec beaucoup plus grand. Si l&#39;officiant principal r&#233;ussit, il gagne de mani&#232;re permanente l&#39;arch&#233;type &lt;a class=&quot;pagelink&quot; href=&quot;Demi-Fi&#233;lon,-Arch&#233;type.html&quot; title=&quot;Demi-fi&#233;lon, arch&#233;type&quot;&gt;demi-fi&#233;lon&lt;/a&gt; et devient &#233;ligible pour entreprendre le &lt;a class=&quot;pagelink&quot; href=&quot;Exemples-De-Rituels-Occultes.html#QUATRIEMEAPOTHEOSE&quot; title=&quot;Exemples de rituels occultes&quot;&gt;quatri&#232;me apoth&#233;ose&lt;/a&gt;.
&lt;/div&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
